/**
 * window.js  --  UI Scaffold window management
 * Generated by uimod_scaffold. DO NOT edit manually; regenerate via scaffold.
 *
 * Exposes a global `wf` object for use in app.js:
 *   wf.root         -- #app-root element
 *   wf.content      -- #content element
 *   wf.cli(cmd, p)  -- inzoi.cli.execute shorthand
 *   wf.save()       -- save window state now
 *   wf.MOD_ID / APP_NAME / TRIGGER_TYPE
 */
(function () {
    'use strict';

    // ------------------------------------------------------------------
    // Required-dependency guard (scaffold safety).
    // index.html MUST load these BEFORE window.js, in this order:
    //   coui://inzoi/cohtml.js        -> defines 'engine'  (game bridge / input forwarding)
    //   coui://inzoi/mod/inzoi-sdk.js -> defines 'inzoi.*' (view.hover, cli, saveState...)
    // If either is missing, hover/input-forwarding and every inzoi.* call below breaks.
    // Surface a loud, actionable diagnostic instead of failing later in obscure ways.
    // ------------------------------------------------------------------
    if (typeof engine === 'undefined' || typeof window.inzoi === 'undefined') {
        var _miss = [];
        if (typeof engine === 'undefined')       { _miss.push('coui://inzoi/cohtml.js (engine)'); }
        if (typeof window.inzoi === 'undefined') { _miss.push('coui://inzoi/mod/inzoi-sdk.js (inzoi)'); }
        console.error('[uimod] index.html is missing required script(s): ' + _miss.join(', ') +
            '. Input forwarding / inzoi.view.hover() / inzoi.* APIs will NOT work. ' +
            'Restore the <script> tags (cohtml.js then inzoi-sdk.js) before window.js.');
    }

    // -- Scaffold-substituted constants --
    var MOD_ID       = 'HouseholdBoard_I6IXIO';
    var APP_NAME     = 'phone';
    var TRIGGER_TYPE = 'game_mode';
    // Manually-activated triggers: user opens and must be able to close.
    // Auto-shown triggers (game_mode, always_on): game manages lifetime.
    var HAS_CLOSE_BTN = (TRIGGER_TYPE === 'interaction_menu' || TRIGGER_TYPE === 'command');

    var root     = document.getElementById('app-root');
    var content  = document.getElementById('content');
    var closeBtn = document.getElementById('close-btn');
    var minBtn   = document.getElementById('minimize-btn');

    // cfg 로드 완료 전까지 body를 숨겨 dirty 레이아웃 깜빡임을 방지한다.
    // visibility:hidden은 레이아웃을 유지하므로 applyWindowState가 올바르게 동작한다.
    if (document.body) document.body.style.visibility = 'hidden';

    function cli(cmd, params) { return inzoi.cli.execute(cmd, params || {}); }

    // ------------------------------------------------------------------
    // setHover: tells the engine whether the cursor is over our UI.
    // NEVER replace with `pointer-events: none` -- breaks inzoi.view.hover().
    // ------------------------------------------------------------------
    function setHover(bOver) {
        try { if (window.inzoi && inzoi.view && inzoi.view.hover) { inzoi.view.hover(bOver); return; } } catch (e) {}
        try {
            if (typeof engine !== 'undefined') {
                engine.call('_uimod_request', JSON.stringify({
                    type: 'view', action: 'hover', over: !!bOver, promiseId: 0
                }));
            }
        } catch (e) {}
    }
    root.addEventListener('mouseenter', function () { setHover(true);  });
    root.addEventListener('mouseleave', function () { setHover(false); });
    root.addEventListener('wheel',      function (e) { e.stopPropagation(); }, { passive: false });

    // ------------------------------------------------------------------
    // _reportContentRect: reports #app-root screen rect to C++ InputRouter.
    // C++ uses this for synchronous wheel/click hit-testing, bypassing the
    // async hover flag timing issue (Advance runs after InputPreProcessor).
    // ------------------------------------------------------------------
    function _reportContentRect() {
        try {
            if (window.inzoi && inzoi.view && inzoi.view.setContentRect) {
                inzoi.view.setContentRect(
                    root.offsetLeft, root.offsetTop,
                    root.offsetWidth, root.offsetHeight);
            }
        } catch (e) {}
    }

    // Bring this view to Z-order front. Fired from the 'click' event (after the
    // full mousedown->mouseup chain, including our synthetic click below) and
    // guarded by _hasFocus so the BringToFront churn happens at most once per
    // pointer entry, never mid-gesture.
    var _hasFocus = true;
    root.addEventListener('click', function () {
        if (_hasFocus) { return; }
        _hasFocus = true;
        try {
            if (typeof engine !== 'undefined') {
                engine.call('_uimod_request', JSON.stringify({
                    type: 'view', action: 'focus', promiseId: 0
                }));
            }
        } catch (e) {}
    }, false);
    root.addEventListener('mouseleave', function () { _hasFocus = false; });

    // ------------------------------------------------------------------
    // Reliable click synthesis.
    // cohtml occasionally fails to emit a native 'click' even when both
    // mousedown and mouseup are delivered (input arrives via a custom
    // IInputProcessor and the widget is SelfHitTestInvisible, so cohtml's
    // internal click synthesis is unreliable). mouseup, however, is 100%
    // reliable. So we synthesize the click on mouseup when the up target
    // matches the down target, and suppress any native click that does
    // arrive to avoid double activation.
    // ------------------------------------------------------------------
    var _downTarget = null;
    var _synthGuard = false;
    root.addEventListener('mousedown', function (e) { _downTarget = e.target; }, true);
    root.addEventListener('mouseup', function (e) {
        var dt = _downTarget; _downTarget = null;
        if (!dt) { return; }
        var up = e.target;
        var same = (up === dt)
                || (dt.contains && dt.contains(up))
                || (up.contains && up.contains(dt));
        if (!same) { return; }
        _synthGuard = true;
        var evt;
        try { evt = new MouseEvent('click', { bubbles: true, cancelable: true }); }
        catch (err) { evt = document.createEvent('MouseEvents'); evt.initEvent('click', true, true); }
        evt._synthetic = true;
        up.dispatchEvent(evt);
        setTimeout(function () { _synthGuard = false; }, 0);
    }, true);
    // Block native (possibly duplicate) clicks while a synthetic one was just fired.
    root.addEventListener('click', function (e) {
        if (e._synthetic) { return; }
        if (_synthGuard) { e.stopImmediatePropagation(); e.preventDefault(); }
    }, true);

    // ------------------------------------------------------------------
    // Close button -- visible only for manually-activated triggers.
    // game_mode / always_on: game manages lifetime, no close button.
    // ------------------------------------------------------------------
    if (HAS_CLOSE_BTN) {
        if (closeBtn) closeBtn.addEventListener('click', function () {
            saveWindowState();
            // Defer hide via setTimeout(0): a synchronous engine.call to RemoveFromParent()
            // while cohtml is still processing the event can reset Slate input state.
            setTimeout(function () {
                try {
                    if (typeof engine !== 'undefined') {
                        engine.call('_uimod_request', JSON.stringify({ type: 'view', action: 'hide', promiseId: 0 }));
                    }
                } catch (e) {}
            }, 0);
        });
    } else {
        if (closeBtn) closeBtn.style.display = 'none';
    }

    // ------------------------------------------------------------------
    // Window state persistence
    // Stored: <mod_root>/ui/<app_name>/saved/window.cfg
    // ------------------------------------------------------------------
    var CFG_SECTION = 'ui/' + APP_NAME + '/saved';
    var CFG_KEY     = 'window';
    var _saveTimer  = null;

    function currentSize() {
        var w = (root._savedW != null) ? root._savedW : root.offsetWidth;
        var h = (root._savedH != null) ? root._savedH : root.offsetHeight;
        return { w: w, h: h };
    }

    function saveWindowState() {
        try {
            var sz = currentSize();
            // When display:none, offsetLeft/Top return 0; fall back to inline style values.
            var x = root.style.left ? parseFloat(root.style.left) : root.offsetLeft;
            var y = root.style.top  ? parseFloat(root.style.top)  : root.offsetTop;
            // Parked against a game-screen edge? Store where it belongs when it comes back out,
            // not the sliver it currently shows (see the docking block below).
            var parked = typeof root._dockSave === 'function' ? root._dockSave() : null;
            if (parked) { x = parked.x; y = parked.y; }
            cli('uimod.cfg_save', {
                mod_id:  MOD_ID,
                section: CFG_SECTION,
                key:     CFG_KEY,
                value:   JSON.stringify({ x: x, y: y, w: sz.w, h: sz.h, minimized: !!root._minimized,
                                          dock: parked ? parked.edge : '' })
            });
        } catch (e) {}
    }

    function saveWindowStateSoon() {
        if (_saveTimer) clearTimeout(_saveTimer);
        _saveTimer = setTimeout(function () { _saveTimer = null; saveWindowState(); }, 120);
    }

    // The game lays the view out a moment after the page starts; until then its size reads 0.
    function viewportLaidOut() {
        return (window.innerWidth || document.documentElement.clientWidth || 0) > 0 &&
            (window.innerHeight || document.documentElement.clientHeight || 0) > 0;
    }

    // The whole phone stays on the game screen. A spot saved on a bigger screen (another
    // resolution, or the game laying the view out at another size) would otherwise leave the
    // phone out of reach, with nothing but a sliver to show for it.
    function clampToViewport(x, y, w, h) {
        var vw = window.innerWidth  || document.documentElement.clientWidth  || 1920;
        var vh = window.innerHeight || document.documentElement.clientHeight || 1080;
        if (typeof w === 'number') w = Math.max(120, Math.min(w, vw));
        if (typeof h === 'number') h = Math.max(60,  Math.min(h, vh));
        if (typeof x === 'number') x = Math.max(0, Math.min(x, vw - (typeof w === 'number' ? w : 0)));
        if (typeof y === 'number') y = Math.max(0, Math.min(y, vh - (typeof h === 'number' ? h : 0)));
        return { x: x, y: y, w: w, h: h };
    }

    // Puts the phone back on the screen as it is now. A parked phone is placed by the docking
    // block (its sliver lies outside the picture on purpose); a free one is kept fully inside.
    function reclampWindow() {
        if (!viewportLaidOut()) return;
        var sz = currentSize();
        var x  = root.style.left ? parseFloat(root.style.left) : root.offsetLeft;
        var y  = root.style.top  ? parseFloat(root.style.top)  : root.offsetTop;
        var c  = clampToViewport(x, y, sz.w, sz.h);
        var changed = false;
        if (c.w !== sz.w || c.h !== sz.h) {
            if (!root._minimized) {
                root.style.width  = c.w + 'px';
                root.style.height = c.h + 'px';
            }
            root._savedW = c.w;
            root._savedH = c.h;
            changed = true;
        }
        var parked = typeof root._dockSave === 'function' ? root._dockSave() : null;
        if (parked) {
            root._dockReapply();
            changed = true;
        } else if (c.x !== x || c.y !== y) {
            root.style.left = c.x + 'px';
            root.style.top  = c.y + 'px';
            changed = true;
        }
        if (changed) saveWindowStateSoon();
        _reportContentRect();
    }

    // Clamps once the game has given the view its size; before that every size reads as the
    // 1920x1080 fallback, and clamping to it would shift a phone on a bigger screen for good.
    var _layoutWait = 0;
    function reclampWhenLaidOut(triesLeft) {
        if (_layoutWait) clearTimeout(_layoutWait);
        _layoutWait = 0;
        if (viewportLaidOut()) { reclampWindow(); return; }
        if (triesLeft <= 0) return;
        _layoutWait = setTimeout(function () { reclampWhenLaidOut(triesLeft - 1); }, 200);
    }

    function applyWindowState(state) {
        if (!state) return;
        var c = viewportLaidOut() ? clampToViewport(state.x, state.y, state.w, state.h)
            : { x: state.x, y: state.y, w: state.w, h: state.h };
        if (typeof c.x === 'number') root.style.left   = c.x + 'px';
        if (typeof c.y === 'number') root.style.top    = c.y + 'px';
        if (typeof c.w === 'number') root.style.width  = c.w + 'px';
        if (typeof c.h === 'number') root.style.height = c.h + 'px';
        root._savedW = (typeof c.w === 'number') ? c.w : null;
        root._savedH = (typeof c.h === 'number') ? c.h : null;
        if (state.minimized && typeof root._applyMinimize === 'function') {
            root._applyMinimize(true);
        }
        // Reopen where it was parked: show the sliver, not the whole phone.
        if (state.dock && typeof root._dockRestore === 'function') {
            root._dockRestore(state.dock, state.x, state.y);
        }
        _reportContentRect();
        reclampWhenLaidOut(50);
    }

    // Re-clamp on viewport size changes (resolution/window-mode swap, monitor disconnect).
    // Reuses the saveWindowStateSoon debounce so we only persist once after the burst settles.
    var _resizeTimer = null;
    window.addEventListener('resize', function () {
        if (_resizeTimer) clearTimeout(_resizeTimer);
        _resizeTimer = setTimeout(function () {
            _resizeTimer = null;
            try { reclampWindow(); } catch (e) {}
        }, 120);
    });

    function loadWindowState() {
        function reveal() { if (document.body) document.body.style.visibility = ''; _reportContentRect(); }
        try {
            var p = cli('uimod.cfg_load', { mod_id: MOD_ID, section: CFG_SECTION, key: CFG_KEY });
            if (p && typeof p.then === 'function') {
                p.then(function (res) {
                    var raw = (res && (res.value || res.data && res.data.value)) || null;
                    if (raw) {
                        try { applyWindowState(JSON.parse(raw)); } catch (e) {}
                    }
                    reveal();
                }).catch(function () { reveal(); });
            } else {
                reveal();
            }
        } catch (e) { reveal(); }
    }

    // Expose for float/resize/minimize snippets.
    root._saveWindowStateSoon = saveWindowStateSoon;
    root._saveWindowState     = saveWindowState;

    // Save on visibility hide AND on page unload (covers always_on unmount)
    document.addEventListener('visibilitychange', function () {
        if (document.hidden) saveWindowState();
    });
    window.addEventListener('beforeunload', function () { saveWindowState(); });

    // Minimize = compact title-bar.
    // - Hide content and resize handle so only the title bar remains.
    // - minimize-btn is hidden while minimized; restore by clicking title bar.
    // - Preserve the ORIGINAL size in root._savedW / _savedH so that
    //   saveWindowState() persists the real size (not the auto-shrunk compact size).
    // NOTE: style.display='' (remove inline override) instead of 'inline-block'
    //       for reliable re-show in cohtml.
    (function() {
        var minBtn   = document.getElementById('minimize-btn');
        var titleBar = document.getElementById('title-bar');
        minBtn.textContent = '_';
        function applyMinimize(bMin) {
            root._minimized = !!bMin;
            if (bMin) {
                // display:none 상태에서 offsetWidth/Height 는 0 반환 -> inline style 우선 읽기
                if (root._savedW == null) root._savedW = root.offsetWidth  || (root.style.width  ? parseFloat(root.style.width)  : null);
                if (root._savedH == null) root._savedH = root.offsetHeight || (root.style.height ? parseFloat(root.style.height) : null);
                content.style.display = 'none';
                var rh = document.getElementById('resize-handle');
                if (rh) rh.style.display = 'none';
                if (minBtn) minBtn.style.display = 'none';
                root.style.width  = 'auto';
                root.style.height = 'auto';
            } else {
                content.style.display = '';
                var rh2 = document.getElementById('resize-handle');
                if (rh2) rh2.style.display = '';
                // '' 로 inline override 제거 -> CSS 규칙(inline-block)이 복원됨
                if (minBtn) minBtn.style.display = '';
                if (root._savedW != null) root.style.width  = root._savedW + 'px';
                if (root._savedH != null) root.style.height = root._savedH + 'px';
            }
            _reportContentRect();
        }
        root._applyMinimize = applyMinimize;
        function toggle() {
            applyMinimize(!root._minimized);
            // 즉시 저장 (디바운스 금지): setTimeout(0)으로 예약된 BringToFront 리로드보다
            // 동기적으로 먼저 실행돼야 리로드 후 올바른 상태를 읽을 수 있다.
            if (typeof root._saveWindowState === 'function') root._saveWindowState();
        }
        minBtn.addEventListener('click', function(e) { toggle(); e.stopPropagation(); });
        // Title-bar click restores when minimized (ignore drag / child buttons).
        titleBar.addEventListener('click', function(e) {
            if (root._wasDragged) return;
            if (e.target.id === 'minimize-btn' || e.target.id === 'close-btn' || e.target.id === 'hide-btn' || (e.target.parentNode && e.target.parentNode.id === 'hide-btn')) return;
            if (root._minimized) toggle();
        });
    })();
    // Drag-to-move via title-bar
    (function() {
        var handle = document.getElementById('title-bar');
        var ox, oy, dragging = false;
        handle.addEventListener('mousedown', function(e) {
            if (e.target.id === 'minimize-btn' || e.target.id === 'close-btn' || e.target.id === 'hide-btn' || (e.target.parentNode && e.target.parentNode.id === 'hide-btn')) return;
            dragging = true; root._wasDragged = false;
            // Grabbing it back out of a parked state also unpins it.
            if (typeof root._dockCancel === 'function') root._dockCancel();
            ox = e.clientX - root.offsetLeft; oy = e.clientY - root.offsetTop;
        });
        document.addEventListener('mousemove', function(e) {
            if (dragging) { root._wasDragged = true; root.style.left = (e.clientX - ox) + 'px'; root.style.top = (e.clientY - oy) + 'px'; }
        });
        document.addEventListener('mouseup', function() {
            if (dragging) {
                dragging = false;
                if (root._wasDragged && typeof root._saveWindowState === 'function') root._saveWindowState();
                _reportContentRect();
                // Released past a game-screen edge -> park it there (see the docking block).
                if (root._wasDragged && typeof root._dockAfterDrag === 'function') root._dockAfterDrag();
            }
        });
    })();
    // Resize
    (function() {
        var rh = document.createElement('div'); rh.id = 'resize-handle'; root.style.overflow = 'hidden'; root.appendChild(rh);
        var sx, sy, sw, sh, resizing = false, resized = false;
        rh.addEventListener('mousedown', function(e) {
            if (root._minimized) return;
            resizing = true; resized = false;
            sx = e.clientX; sy = e.clientY; sw = root.offsetWidth; sh = root.offsetHeight;
            e.stopPropagation();
        });
        document.addEventListener('mousemove', function(e) {
            if (resizing) {
                resized = true;
                var nw = Math.max(120, sw + e.clientX - sx);
                var nh = Math.max(60,  sh + e.clientY - sy);
                root.style.width  = nw + 'px';
                root.style.height = nh + 'px';
                root._savedW = nw;
                root._savedH = nh;
            }
        });
        document.addEventListener('mouseup', function() {
            if (resizing) {
                resizing = false;
                if (resized && typeof root._saveWindowState === 'function') root._saveWindowState();
                _reportContentRect();
            }
        });
    })();

    // ------------------------------------------------------------------
    // Parking against a game-screen edge (local addition -- not from the scaffold).
    //
    // Drag the phone past the edge of the game picture and let go: it tucks itself away so
    // only a hair of the frame shows, the way a picture-in-picture window parks against a
    // screen edge. Move the pointer back onto that hair and the whole phone slides out;
    // move off it and it goes back in. The edges here are the game screen (this view's
    // viewport), not the phone's own box.
    //
    // Motion is frame-driven, like the app's own page transitions: cohtml has no dependable
    // CSS transitions, and a timer ends every slide so a stalled frame loop can never leave
    // the phone stranded half way across an edge.
    // ------------------------------------------------------------------
    (function () {
        var PEEK_PX     = 16;    // how much of the phone stays on screen while parked
        var DOCK_SHARE  = 0.5;   // more than this much past an edge = park it on that edge
        var OUT_MS      = 300;   // slide back out
        var IN_MS       = 250;   // tuck in
        var LINGER_MS   = 450;   // grace after the pointer leaves before it tucks itself
        var raf = window.requestAnimationFrame
            ? function (f) { window.requestAnimationFrame(f); }
            : function (f) { setTimeout(f, 16); };

        var edge = '';           // '', 'left' | 'right' | 'top' | 'bottom'
        var home = null;         // where it sits fully out, flush against that edge
        var opened = false;      // currently out
        var parkedAt = 0;        // when it last tucked in, so the release itself cannot pop it out
        var anim = null;
        var linger = 0;
        var openedAt = 0;
        // An input method's candidate list is its own window outside the phone: turning to its
        // next page with the mouse takes the pointer off the phone. Tucking away then blurs the
        // field, and the input method writes the half-typed pinyin into it as letters. While a
        // word is being composed the phone stays out; it tucks once the word is done.
        var composing = false;
        var pointerOut = false;

        function textFocused() {
            var a = document.activeElement;
            var tag = a && a.tagName ? String(a.tagName).toUpperCase() : '';
            return (tag === 'TEXTAREA' || tag === 'INPUT') && root.contains(a);
        }
        function stillComposing() {
            if (composing && !textFocused()) composing = false;
            return composing;
        }
        function composeDone() {
            composing = false;
            if (edge && opened && pointerOut) {
                clearTimeout(linger);
                linger = setTimeout(retreat, LINGER_MS);
            }
        }
        document.addEventListener('compositionstart', function () { composing = true; }, true);
        document.addEventListener('compositionend', composeDone, true);
        document.addEventListener('blur', function () { if (composing && !textFocused()) composeDone(); }, true);

        function vw() { return window.innerWidth  || document.documentElement.clientWidth  || 1920; }
        function vh() { return window.innerHeight || document.documentElement.clientHeight || 1080; }
        function size() {
            var w = root.offsetWidth  || (root.style.width  ? parseFloat(root.style.width)  : 0);
            var h = root.offsetHeight || (root.style.height ? parseFloat(root.style.height) : 0);
            return { w: w, h: h };
        }
        function here() {
            return {
                x: root.style.left ? parseFloat(root.style.left) : root.offsetLeft,
                y: root.style.top  ? parseFloat(root.style.top)  : root.offsetTop
            };
        }
        function clampX(x, w) { return Math.max(0, Math.min(x, vw() - w)); }
        function clampY(y, h) { return Math.max(0, Math.min(y, vh() - h)); }
        function easeOut(t) { return 1 - Math.pow(1 - t, 3); }

        function stopAnim() {
            if (!anim) return;
            clearTimeout(anim.timer);
            anim = null;
        }

        function slideTo(x, y, ms, done) {
            stopAnim();
            var from = here();
            var token = { timer: 0 };
            var t0 = Date.now();
            var frames = 0;
            anim = token;
            function end() {
                if (anim !== token) return;
                clearTimeout(token.timer);
                anim = null;
                root.style.left = x + 'px';
                root.style.top  = y + 'px';
                _reportContentRect();
                if (done) done();
            }
            function step() {
                if (anim !== token) return;
                var t = Math.min(1, (Date.now() - t0) / ms);
                if (t >= 1) { end(); return; }
                var k = easeOut(t);
                root.style.left = (from.x + (x - from.x) * k) + 'px';
                root.style.top  = (from.y + (y - from.y) * k) + 'px';
                // Input hit-testing follows the reported rect, so keep it tracking the slide.
                if ((frames++ & 1) === 0) _reportContentRect();
                raf(step);
            }
            token.timer = setTimeout(end, ms + 180);
            raf(step);
        }

        function tuckedX() {
            var s = size();
            if (edge === 'left')  return -(s.w - PEEK_PX);
            if (edge === 'right') return vw() - PEEK_PX;
            return home ? home.x : here().x;
        }
        function tuckedY() {
            var s = size();
            if (edge === 'top')    return -(s.h - PEEK_PX);
            if (edge === 'bottom') return vh() - PEEK_PX;
            return home ? home.y : here().y;
        }

        function paint() {
            root._dockEdgeId = edge;
            root.classList.remove('dock-left');
            root.classList.remove('dock-right');
            root.classList.remove('dock-top');
            root.classList.remove('dock-bottom');
            root.classList.remove('dock-open');
            if (edge) root.classList.add('dock-' + edge);
            if (edge && opened) root.classList.add('dock-open');
        }

        function park(which) {
            var s = size(), p = here();
            clearTimeout(linger);
            edge = which;
            opened = false;
            parkedAt = Date.now();   // the pointer is still on the sliver; don't pop straight out
            home = {
                x: which === 'left' ? 0 : (which === 'right' ? vw() - s.w : clampX(p.x, s.w)),
                y: which === 'top' ? 0 : (which === 'bottom' ? vh() - s.h : clampY(p.y, s.h))
            };
            paint();
            slideTo(tuckedX(), tuckedY(), IN_MS);
            if (typeof root._saveWindowState === 'function') root._saveWindowState();
        }

        function reveal() {
            if (!edge || opened) return;
            clearTimeout(linger);
            opened = true;
            openedAt = Date.now();
            paint();
            slideTo(home.x, home.y, OUT_MS);
        }

        function retreat() {
            if (!edge || !opened) return;
            if (stillComposing()) return;   // composeDone tucks it once the word is finished
            opened = false;
            // A field that was being typed into must not keep the keyboard: the phone is going
            // away, so the game gets the keys back.
            try {
                var a = document.activeElement;
                if (a && a !== document.body && a.blur) a.blur();
            } catch (e) {}
            paint();
            slideTo(tuckedX(), tuckedY(), IN_MS);
            if (typeof root._saveWindowState === 'function') root._saveWindowState();
        }

        // Called when a drag ends: tuck against whichever edge the phone mostly went past,
        // otherwise settle it back inside the picture the way it was.
        function afterDrag() {
            var s = size(), p = here();
            var over = { left: -p.x, right: p.x + s.w - vw(), top: -p.y, bottom: p.y + s.h - vh() };
            var best = '', most = 0;
            if (over.left > most)   { most = over.left;   best = 'left'; }
            if (over.right > most)  { most = over.right;  best = 'right'; }
            if (over.top > most)    { most = over.top;    best = 'top'; }
            if (over.bottom > most) { most = over.bottom; best = 'bottom'; }
            var span = (best === 'left' || best === 'right') ? s.w : s.h;
            if (best && most >= span * DOCK_SHARE) { park(best); return; }
            clearTimeout(linger);
            edge = '';
            opened = false;
            home = null;
            paint();
            var x = clampX(p.x, s.w), y = clampY(p.y, s.h);
            var save = function () { if (typeof root._saveWindowState === 'function') root._saveWindowState(); };
            if (Math.abs(x - p.x) > 1 || Math.abs(y - p.y) > 1) slideTo(x, y, 180, save);
            else save();
        }

        // Hovering the sliver brings the phone back out. The short guard after parking keeps
        // the release that parked it (pointer still on the sliver) from popping it straight
        // back out; a real hover always comes later than that.
        root.addEventListener('mouseenter', function () {
            pointerOut = false;
            if (edge && !opened && Date.now() - parkedAt > 260) reveal();
        });
        root.addEventListener('mouseleave', function () {
            pointerOut = true;
            if (!edge) return;
            if (!opened) return;
            // The rect is moving while the phone slides out and hit-testing follows it, which
            // can read as a leave in the middle of the slide. That is not the player leaving.
            if (Date.now() - openedAt < OUT_MS + 80) return;
            clearTimeout(linger);
            linger = setTimeout(retreat, LINGER_MS);
        });

        root._dockAfterDrag = afterDrag;
        root._dockCancel = function () {
            clearTimeout(linger);
            if (!edge) return;
            edge = '';
            opened = false;
            home = null;
            paint();
        };
        root._dockSave = function () {
            return edge && home ? { x: home.x, y: home.y, edge: edge } : null;
        };
        // The saved spot is from the game screen of that session; the screen may be smaller now
        // (another resolution, or the game laying the view out at another size), and a phone
        // that slides out past the edge can never be reached again. It is placed again on
        // today's screen: flush against its edge, and inside the picture along it.
        function rehome(x, y) {
            var s = size();
            home = {
                x: edge === 'left' ? 0 : (edge === 'right' ? vw() - s.w : clampX(x, s.w)),
                y: edge === 'top' ? 0 : (edge === 'bottom' ? vh() - s.h : clampY(y, s.h))
            };
        }
        root._dockRestore = function (which, x, y) {
            if (which !== 'left' && which !== 'right' && which !== 'top' && which !== 'bottom') return;
            clearTimeout(linger);
            stopAnim();
            edge = which;
            // Before the view has its size the screen is not known yet; the saved spot is kept
            // as it is and placed once the view is laid out (_dockReapply).
            if (viewportLaidOut()) rehome(x, y);
            else home = { x: x, y: y };
            opened = false;
            parkedAt = 0;   // nothing is hovering yet, so the first approach should open it
            paint();
            root.style.left = tuckedX() + 'px';
            root.style.top  = tuckedY() + 'px';
        };
        root._dockReapply = function () {
            if (!edge) return;
            stopAnim();
            rehome(home ? home.x : here().x, home ? home.y : here().y);
            root.style.left = (opened ? home.x : tuckedX()) + 'px';
            root.style.top  = (opened ? home.y : tuckedY()) + 'px';
        };
    })();

    // Load saved state last (minimize snippet must have installed root._applyMinimize first).
    loadWindowState();

    // ------------------------------------------------------------------
    // SaveState: wf.state auto-persists across game save/load.
    //   - On game save (auto/manual): C++ calls __uimod_collectSaveState()
    //     which serializes _appState into the save file's UIMD chunk.
    //   - On game load:   __uimod_deliverLoadedState() restores _appState and
    //     invokes window._onStateLoaded(state) if defined in app.js.
    //   - On in-session trigger hide/show, CityEdit / Build mode entry:
    //     UB1UIModView::Hide() toggles visibility only (does NOT destroy the
    //     cohtml view). The JS context stays alive, so _appState survives
    //     in memory without any disk mirror. No special handling needed.
    //   - No save = no persist: when the player exits to the main menu the
    //     view is destroyed and unsaved _appState is dropped; the next session
    //     restores from the UIMD chunk (= last successful save) only.
    // ------------------------------------------------------------------
    var _appState = {};

    inzoi.saveState.register(function () {
        return Object.keys(_appState).length > 0 ? _appState : null;
    });

    inzoi.saveState.onLoad(function (json) {
        try {
            var saved = JSON.parse(json);
            for (var k in saved) {
                if (saved.hasOwnProperty(k)) {
                    _appState[k] = saved[k];
                }
            }
            if (typeof window._onStateLoaded === 'function') {
                window._onStateLoaded(_appState);
            }
        } catch (e) {}
    });

    // ------------------------------------------------------------------
    // Public API for app.js
    // ------------------------------------------------------------------
    window.wf = {
        root:         root,
        content:      content,
        cli:          cli,
        save:         saveWindowState,
        state:        _appState,
        MOD_ID:       MOD_ID,
        APP_NAME:     APP_NAME,
        TRIGGER_TYPE: TRIGGER_TYPE
    };
})();